const TIME_LIMIT: int = 3125;
const OPENING_BUFFER: int = 120;
const TH15_TALISMAN: int = 528;

// BCirC03Dead: ANIM's -4*initial_velocity displacement is applied at fire.
// Birth animation/protection is omitted as approved. VELTIME(60,4,keep_angle)
// is collinear here, so its (4-1)/60 slope is an along-angle acceleration.
xformdef CROWN_ACCEL {
    @60 set_accel(0.05fx);
    set_accel(0fx);
}

sub death_fan() {
    var rank: int = global(GVAR_RANK);
    var count: int = 3;
    var spacing: int = 5063; // 0.485403 rad, E/N/L
    if rank == 2 { count = 5; spacing = 3641; } // 0.349066 rad
    if rank == 3 { count = 9; }
    // FINAL_ANGLE is the displacement direction; this single-layer straight
    // flight has the same direction as the live enemy velocity.
    var axis: int = $self_angle as int;
    var x: fx = $self_x;
    var y: fx = $self_y;
    // etAim(1): fixed fan, source creation order center, negative, positive.
    for i in 0..count {
        var offset: int = ((i + 1) / 2) * spacing;
        if i % 2 != 0 { offset = -offset; }
        var a: angle = (axis + offset) as angle;
        _ = fire(TH15_TALISMAN, 13,
            x - 4fx * cos(a), y - 4fx * sin(a),
            1fx, a, CROWN_ACCEL, none);
    }
    // BI3 += 50 is damage feedback and is omitted by this task's approval.
}

async sub carrier(direction: angle) {
    // BCirC03 645-679; inherited F0 is captured at creation, not shared.
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    set_enemy_flag(ENEMY_NO_BODY, 1); // flagSet(15), first 30 frames
    move_vel(0, direction, 2fx, EASE_LINEAR);
    wait(30);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    move_speed(120, 10fx, EASE_LINEAR);
    wait(30);
    // Approved synthesis: fixed age 60 replaces player-triggered setDeath.
    // The enemy disappears after exactly one BCirC03Dead fan.
    death_fan();
}

sub crown_schedule() {
    // BossCard3_at 1612-1643: ONE random F0 sample, then +3.883222
    // before each relative enmCreate. Q8 BAM retains fractional increments.
    var phase: int = (rand(65536) - 32768) * 256;
    var delay: int = 3;
    var rank: int = global(GVAR_RANK);
    if rank == 3 { delay = 1; }
    for e in 0..13000 {
        phase = (phase + 10368890) % 16777216;
        _ = spawn_enemy($self_x, $self_y, 100, 0, 0, 0,
            carrier((phase / 256) as angle));
        // E starts at -1 and is incremented BEFORE creation. The changed
        // wait applies after spawn number 61 / 181, not one spawn earlier.
        if e == 60 { delay = 2; }
        if e == 180 { delay = 1; }
        if rank == 0 { wait(delay * 2); }
        else { wait(delay); }
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // BossCard3 1549-1555: retain four entry-cleanup frames before reset.
    wait(4);
    // Source timer 0. No previous enemies, bullets, async or residual velocity.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    // moveLimit(0,144,240,64) is inactive throughout this path:
    // x=0, y stays in [128,144], within x=[-120,120], y=[112,176].
    wait(90);
    // Source @BossCard3_at() is SYNCHRONOUS. Its 13000 creations cannot
    // finish inside this 3000-frame phase; the parent's wait(120) is unreachable.
    crown_schedule();
    loop { wait(1000); }
}

async sub boss() {
    // Real Boss carries the independent invincible phase; no separate bodyless
    // control enemy. Entry position (0,128), HP 2500, hitbox48/hurtbox40.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // Pattern starts next frame: 120 opening + 4 cleanup + 1 dispatch + 3000.
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Boss4 is only the successor boundary. Remove surviving carriers and
    // their pending fixed-age death fans, without executing death callbacks.
    kill_all_enemies(KILL_SILENT);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2500, 0, 0, 0, boss);
    loop { wait(600); }
}
